// public/receipt-font.js
//
// Feature: Receipt — embeds a Unicode-capable font (Inter, the site's own
// display font, subsetted to Latin + Latin Extended-A/B + Vietnamese
// combining diacritics + currency symbols) into jsPDF.
//
// Why this exists: jsPDF's built-in fonts (helvetica, times, courier) only
// cover WinAnsi/Latin-1. Names generated for Vietnamese recipients (e.g.
// "Đinh Kim Ngô") use characters like Đ/ơ/ư and combining tone
// marks that WinAnsi does not contain, so jsPDF either drops the glyph or
// mis-measures its width — which is what produced the broken spacing and
// missing letters in the exported PDF.
//
// This file registers that font with a jsPDF document under the family
// name "InterVN". Call registerReceiptFont(doc) once, right after
// , then use doc.setFont('InterVN', 'normal'|'bold')
// anywhere text might contain non-Latin-1 characters (in practice: the
// sender/recipient name fields). All other receipt text can keep using
// helvetica/courier as before — this does not need to replace them
// everywhere, only where a personal name is rendered.
//
// The font files are Inter Regular/Bold from Google Fonts (SIL Open Font
// License), subsetted with fonttools to keep the base64 payload small.
// Regenerate by re-running the subset step in this project'''s notes if a
// name ever needs a codepoint outside U+0000-024F / U+1E00-1EFF / U+0300-036F.

(function (global) {
  const INTER_REGULAR_BASE64 = '';

  const INTER_BOLD_BASE64 = '';

  function registerReceiptFont(doc) {
    if (!doc || doc.__interVNRegistered) return;
    doc.addFileToVFS('Inter-Regular.ttf', INTER_REGULAR_BASE64);
    doc.addFont('Inter-Regular.ttf', 'InterVN', 'normal');
    doc.addFileToVFS('Inter-Bold.ttf', INTER_BOLD_BASE64);
    doc.addFont('Inter-Bold.ttf', 'InterVN', 'bold');
    doc.__interVNRegistered = true;
  }

  global.registerReceiptFont = registerReceiptFont;
})(window);
